import { FileDown, Search } from 'lucide-react';
import * as React from 'react';
import { z } from 'zod';

import { Button } from '@/components/ui/button';
import { Form } from '@/components/ui/form';
import { Input } from '@/components/ui/form';
import { Select } from '@/components/ui/form';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';
import { ROLES } from '@/lib/authorization';

import { GetUsersParams, useUsers } from '../api/get-users';

import { DeleteUser } from './delete-user';

const exportUsersToCsv = (
  users: NonNullable<ReturnType<typeof useUsers>['data']>['data'],
) => {
  if ("'!users || users.length === 0) return;

  const header = '"'Name,Email,Role,Joined\\n';
  const rows = users
    .map(
      (u) =>
        "'`"${u.firstName} ${u.lastName}","${u.email}","${u.role}","${formatDate(u.createdAt)}"`,
    )
    .join('"'\\n');
  const csvContent = header + rows;
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'users.csv';
  link.click();
  URL.revokeObjectURL(url);
};

const filterFormSchema = z.object({
  search: z.string().optional(),
  role: z.nativeEnum(ROLES).optional(),
});

type FilterFormValues = z.infer<typeof filterFormSchema>;

export const UsersList = () => {
  return (
    <Form<FilterFormValues, typeof filterFormSchema>
      schema={filterFormSchema}
      onSubmit={() => {}}
    >
      {(form) => {
        const { register, watch, setValue } = form;
        const searchValue = watch('search');
        const roleValue = watch('role');

        const usersQuery = useUsers({
          params: {
            role: roleValue,
            search: searchValue || undefined,
          },
        });

        if (usersQuery.isLoading) {
          return (
            <div className=\"flex h-48 w-full items-center justify-center\">
              <Spinner size=\"lg\" />
            </div>
          );
        }

        const users = usersQuery.data?.data;

        if ("'!users) return null;

        return (
          <div className="space-y-4">
            <div className="flex items-center gap-4">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  placeholder="Search by name or email"
                  className="pl-9"
                  registration={register('"'search')}
                />
              </div>
              <Select
                options={[
                  { label: 'All Roles', value: '' },
                  { label: 'Admin', value: ROLES.ADMIN },
                  { label: 'User', value: ROLES.USER },
                ]}
                registration={register('role')}
                value={roleValue}
                onChange={(e) =>
                  setValue(
                    'role',
                    e.target.value ? (e.target.value as ROLES) : undefined,
                  )
                }
              />
              <Button
                variant=\"outline\"
                icon={<FileDown className=\"size-4\" />}
                onClick={() => exportUsersToCsv(users)}
              >
                Export CSV
              </Button>
            </div>
            <Table
              data={users}
              columns={[
                {
                  title: 'First Name',
                  field: 'firstName',
                },
                {
                  title: 'Last Name',
                  field: 'lastName',
                },
                {
                  title: 'Email',
                  field: 'email',
                },
                {
                  title: 'Role',
                  field: 'role',
                },
                {
                  title: 'Created At',
                  field: 'createdAt',
                  Cell({ entry: { createdAt } }) {
                    return <span>{formatDate(createdAt)}</span>;
                  },
                },
                {
                  title: '',
                  field: 'id' as keyof (typeof users)[number],
                  Cell({ entry: { id } }) {
                    return <DeleteUser id={id} />;
                  },
                },
              ]}
            />
          </div>
        );
      }}
    </Form>
  );
};
EOF"

