import { queryOptions, useQuery } from '@tanstack/react-query';
import { z } from 'zod';

import { api } from '@/lib/api-client';
import { QueryConfig } from '@/lib/react-query';
import { ROLES } from '@/lib/authorization';
import { User } from '@/types/api';

export const filterUsersSchema = z.object({
  role: z.nativeEnum(ROLES).optional(),
  search: z.string().optional(),
});

export type FilterUsersInput = z.infer<typeof filterUsersSchema>;

export type GetUsersParams = FilterUsersInput;

export const getUsers = (
  params?: GetUsersParams,
): Promise<{ data: User[] }> => {
  return api.get("'`/users`, { params });
};

export const getUsersQueryOptions = (params?: GetUsersParams) => {
  return queryOptions({
    queryKey: ['"'users', params],
    queryFn: () => getUsers(params),
  });
};

type UseUsersOptions = {
  queryConfig?: QueryConfig<typeof getUsersQueryOptions>;
};

export const useUsers = ({
  queryConfig,
  params,
}: UseUsersOptions & { params?: GetUsersParams } = {}) => {
  return useQuery({
    ...getUsersQueryOptions(params),
    ...queryConfig,
  });
};
